import 'package:cerne/core/network/api_client.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:cerne/features/entries/domain/entities/entries_page.dart';
import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:fpdart/fpdart.dart';

const _malformedEntriesFailure = ValidationFailure(
  message: 'Malformed entries response',
  requestId: '',
);

/// The only class that calls `ApiClient.call('entries-create'/'entries-list'/
/// 'entries-get', ...)` and parses the [Entry]/[EntriesPage] response shapes
/// (data-model.md, contracts/entries-repository-extension.md). Never sends
/// `occurredAt`/`mediaDurationSeconds`/`chatMessageId` in a request body.
class EntriesRemoteDataSource {
  const EntriesRemoteDataSource(this._apiClient);

  final ApiClient _apiClient;

  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
  }) async {
    final result = await _apiClient.call(
      'entries-create',
      method: 'POST',
      body: {'content': content, 'source': source.name},
    );

    return result.flatMap(_parseEntry);
  }

  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int? limit,
  }) async {
    final queryParameters = <String, String>{
      'cursor': ?cursor,
      'source': ?source?.name,
      'dateFrom': ?dateFrom?.toUtc().toIso8601String(),
      'dateTo': ?dateTo?.toUtc().toIso8601String(),
      'limit': ?limit?.toString(),
    };
    final result = await _apiClient.call(
      'entries-list',
      method: 'GET',
      queryParameters: queryParameters.isEmpty ? null : queryParameters,
      unwrapData: false,
    );

    return result.flatMap(_parseEntriesPage);
  }

  Future<Either<Failure, Entry>> getById(String id) async {
    final result = await _apiClient.call(
      'entries-get',
      method: 'GET',
      pathSegments: [id],
    );

    return result.flatMap(_parseEntry);
  }

  Future<Either<Failure, List<Entry>>> search({
    String? q,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
    int limit = 50,
  }) async {
    final result = await _apiClient.call(
      'entries-search',
      method: 'GET',
      queryParameters: {
        if (q != null && q.isNotEmpty) 'q': q,
        if (source != null) 'source': source.name,
        if (dateFrom != null) 'dateFrom': dateFrom.toUtc().toIso8601String(),
        if (dateTo != null) 'dateTo': dateTo.toUtc().toIso8601String(),
        'limit': limit.toString(),
      },
      unwrapData: false,
    );

    return result.flatMap(_parseSearchResults);
  }

  Either<Failure, List<Entry>> _parseSearchResults(Map<String, dynamic> body) {
    try {
      final entries = (body['data'] as List<dynamic>)
          .map((e) => _parseEntryFields(e as Map<String, dynamic>))
          .toList();
      return Right(entries);
    } on TypeError {
      return const Left(_malformedEntriesFailure);
    } on FormatException {
      return const Left(_malformedEntriesFailure);
    }
  }

  Either<Failure, Entry> _parseEntry(Map<String, dynamic> data) {
    try {
      return Right(_parseEntryFields(data));
    } on TypeError {
      return const Left(_malformedEntriesFailure);
    } on FormatException {
      return const Left(_malformedEntriesFailure);
    }
  }

  // The full response body for `entries-list` is `{"data": [...], "meta":
  // {"nextCursor": ...}}` — `ApiClient.call(..., unwrapData: false)` returns
  // it verbatim since the inner "data" here is an array, not an object.
  Either<Failure, EntriesPage> _parseEntriesPage(Map<String, dynamic> body) {
    try {
      final entries = (body['data'] as List<dynamic>)
          .map((e) => _parseEntryFields(e as Map<String, dynamic>))
          .toList();
      final meta = body['meta'] as Map<String, dynamic>;
      return Right(
        EntriesPage(
          entries: entries,
          nextCursor: meta['nextCursor'] as String?,
        ),
      );
    } on TypeError {
      return const Left(_malformedEntriesFailure);
    } on FormatException {
      return const Left(_malformedEntriesFailure);
    }
  }

  Entry _parseEntryFields(Map<String, dynamic> data) {
    return Entry(
      id: data['id'] as String,
      content: data['content'] as String,
      source: EntrySource.values.byName(data['source'] as String),
      chatMessageId: data['chatMessageId'] as String?,
      occurredAt: DateTime.parse(data['occurredAt'] as String),
      tags: (data['tags'] as List<dynamic>)
          .map(
            (t) => EntryTag(
              id: (t as Map<String, dynamic>)['id'] as String,
              name: t['name'] as String,
            ),
          )
          .toList(),
      piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
      piiSpans: (data['piiSpans'] as List<dynamic>)
          .map(
            (s) => PiiSpan(
              start: (s as Map<String, dynamic>)['start'] as int,
              end: s['end'] as int,
              type: s['type'] as String,
            ),
          )
          .toList(),
      embeddingStatus: EmbeddingStatus.values.byName(
        data['embeddingStatus'] as String,
      ),
      mediaDurationSeconds: data['mediaDurationSeconds'] as int?,
      serverRevision: data['serverRevision'] as int,
      createdAt: DateTime.parse(data['createdAt'] as String),
      updatedAt: DateTime.parse(data['updatedAt'] as String),
      similarity: (data['similarity'] as num?)?.toDouble(),
    );
  }
}

import 'dart:convert';

import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for the entries the user has
/// already seen (the PRD's "local read cache" — requirements.md line 50/125:
/// results from it stay visible offline and reconcile with the server on
/// reconnect, with no duplicates). Keychain-backed, same pattern as
/// `VaultSecureStorage` — journal content is personal data, so it stays
/// encrypted at rest like the PIN it already sits behind.
///
/// Distinct from `EntriesRepositoryImpl`'s in-memory `cachedEntries`: that
/// field only ever held optimistic just-created entries for this process's
/// lifetime (research.md R8, 003-multimodal-capture). This class is what
/// makes that same list survive an app restart, which is what a cold open
/// on an already-offline device needs (closing snapshot at unit completion
/// did not cover this path — see Meus Registros intervention report).
class EntriesLocalCache {
  EntriesLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _key = 'entriesLocalCache';

  Future<List<Entry>> readAll() async {
    final raw = await _storage.read(key: _key);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded.map((e) => _fromJson(e as Map<String, dynamic>)).toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeAll(List<Entry> entries) {
    final encoded = jsonEncode(entries.map(_toJson).toList());
    return _storage.write(key: _key, value: encoded);
  }

  Map<String, dynamic> _toJson(Entry e) => {
    'id': e.id,
    'content': e.content,
    'source': e.source.name,
    'chatMessageId': e.chatMessageId,
    'occurredAt': e.occurredAt.toUtc().toIso8601String(),
    'tags': [
      for (final tag in e.tags) {'id': tag.id, 'name': tag.name},
    ],
    'piiStatus': e.piiStatus.name,
    'piiSpans': [
      for (final span in e.piiSpans)
        {'start': span.start, 'end': span.end, 'type': span.type},
    ],
    'embeddingStatus': e.embeddingStatus.name,
    'mediaDurationSeconds': e.mediaDurationSeconds,
    'serverRevision': e.serverRevision,
    'createdAt': e.createdAt.toUtc().toIso8601String(),
    'updatedAt': e.updatedAt.toUtc().toIso8601String(),
    'similarity': e.similarity,
  };

  Entry _fromJson(Map<String, dynamic> data) => Entry(
    id: data['id'] as String,
    content: data['content'] as String,
    source: EntrySource.values.byName(data['source'] as String),
    chatMessageId: data['chatMessageId'] as String?,
    occurredAt: DateTime.parse(data['occurredAt'] as String),
    tags: (data['tags'] as List<dynamic>)
        .map(
          (t) => EntryTag(
            id: (t as Map<String, dynamic>)['id'] as String,
            name: t['name'] as String,
          ),
        )
        .toList(),
    piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
    piiSpans: (data['piiSpans'] as List<dynamic>)
        .map(
          (s) => PiiSpan(
            start: (s as Map<String, dynamic>)['start'] as int,
            end: s['end'] as int,
            type: s['type'] as String,
          ),
        )
        .toList(),
    embeddingStatus: EmbeddingStatus.values.byName(
      data['embeddingStatus'] as String,
    ),
    mediaDurationSeconds: data['mediaDurationSeconds'] as int?,
    serverRevision: data['serverRevision'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
    similarity: (data['similarity'] as num?)?.toDouble(),
  );
}

import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// The plain generic loading indicator every Save/recognition call in this
/// unit shows — no dedicated multi-state recognition screen (FR-007).
///
/// A fixed-length arc that only rotates (prototype-extract.md's "Continuous
/// spinner (`spin`, 1 s linear infinite) in every loading state") rather
/// than Material's default indeterminate `CircularProgressIndicator`, whose
/// arc length itself pulses between near-zero and near-full — at the
/// near-zero point it reads as a short dash instead of a ring.
class CaptureLoadingIndicator extends StatefulWidget {
  const CaptureLoadingIndicator({super.key});

  @override
  State<CaptureLoadingIndicator> createState() =>
      _CaptureLoadingIndicatorState();
}

class _CaptureLoadingIndicatorState extends State<CaptureLoadingIndicator>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 1),
    )..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      child: SizedBox(
        width: DesignTokens.sizeLoadingIndicator,
        height: DesignTokens.sizeLoadingIndicator,
        child: RotationTransition(
          turns: _controller,
          child: const CircularProgressIndicator(
            strokeWidth: DesignTokens.strokeWidthLoadingIndicator,
            value: DesignTokens.valueLoadingIndicatorArc,
          ),
        ),
      ),
    );
  }
}

/// The prototype's actual "Erro" shape (prototype-extract.md §2.3,
/// research.md R4): a warning icon, the exact failure copy, an outline
/// "Tentar novamente" button, and — for Foto's "Salvar só a foto" only — an
/// optional secondary text action. Renders both Áudio's and Foto's "Erro"
/// states.
class RecognitionErrorView extends StatelessWidget {
  const RecognitionErrorView({
    required this.message,
    required this.onRetry,
    this.secondaryAction,
    super.key,
  });

  final String message;
  final VoidCallback onRetry;

  /// A `(label, onTap)` pair — used only by Foto's "Salvar só a foto"
  /// (US4); left `null` for Áudio.
  final (String, VoidCallback)? secondaryAction;

  @override
  Widget build(BuildContext context) {
    final secondary = secondaryAction;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        const Icon(
          Icons.error_outline,
          size: DesignTokens.sizeStatusIcon,
          color: DesignTokens.colorError,
        ),
        const SizedBox(height: DesignTokens.spacingSm),
        Text(
          message,
          textAlign: TextAlign.center,
          style: DesignTokens.textBodyMd.copyWith(color: DesignTokens.colorError),
        ),
        const SizedBox(height: DesignTokens.spacingMd),
        OutlinedButton(
          onPressed: onRetry,
          style: OutlinedButton.styleFrom(
            padding: const EdgeInsets.symmetric(
              horizontal: DesignTokens.spacingMd,
              vertical: DesignTokens.spacingSm,
            ),
          ),
          child: const Text('Tentar novamente'),
        ),
        if (secondary != null) ...[
          const SizedBox(height: DesignTokens.spacingSm),
          TextButton(onPressed: secondary.$2, child: Text(secondary.$1)),
        ],
      ],
    );
  }
}

/// Shown in place of the recording/capture controls (Edge Cases).
class CapturePermissionDeniedMessage extends StatelessWidget {
  const CapturePermissionDeniedMessage({required this.message, super.key});

  final String message;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Text(
        message,
        textAlign: TextAlign.center,
        style: DesignTokens.textBodyMd.copyWith(
          color: DesignTokens.colorTextSecondary,
        ),
      ),
    );
  }
}

